struct LowerText;

impl TextFunctions for LowerText {
    fn sanitize_title(&self, s: &[u8]) -> Vec<u8> {
        s.to_ascii_lowercase()
    }
    fn sanitize_html_class(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
    fn esc_html(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
    fn esc_attr(&self, s: &[u8]) -> Vec<u8> {
        s.to_vec()
    }
}

fn deps() -> ThemeJsonDeps {
    let blocks = MemoryBlockMetadata::new();
    for (name, styles) in [
        ("core/group", vec!["a".to_owned()]),
        ("core/paragraph", vec![]),
    ] {
        blocks.register(RegisteredBlock {
            name: name.to_owned(),
            selectors: Value::Null,
            supports: Value::Null,
            style_names: styles,
        });
    }
    ThemeJsonDeps::new(
        Rc::new(blocks),
        Rc::new(LowerText),
        Rc::new(NoTranslation),
        Rc::new(RecordedDiagnostics::default()),
        support::safe_css(),
    )
}

/// Constructs each layer and merges it into the first, as the resolver does.
fn merge_layers(layers: &[(Value, &[u8])]) -> ThemeJson {
    let deps = deps();
    let mut iter = layers.iter();
    let (first, origin) = iter.next().unwrap();
    let mut base = construct(first.clone(), origin, &deps);
    for (data, origin) in iter {
        base = merge(&base, &construct(data.clone(), origin, &deps), &deps);
    }
    base
}

fn raw(doc: ThemeJson) -> Value {
    ThemeJsonCodec::encode(&doc)
}

#[test]
fn replaces_recursively_and_appends_new_keys() {
    let actual = raw(merge_layers(&[
        (
            json(
                r##"{"version":3,"settings":{"color":{"custom":false,"palette":[{"slug":"red","color":"#f00","name":"Red"}]}},"styles":{"blocks":{"core/group":{"color":{"text":"a"}},"core/paragraph":{"color":{"text":"b"}}}}}"##,
            ),
            b"default",
        ),
        (
            json(
                r##"{"version":3,"settings":{"color":{"custom":true,"text":false,"palette":[{"slug":"blue","color":"#00f","name":"Blue"}]}},"styles":{"blocks":{"core/paragraph":{"color":{"background":"c"}},"core/group":{"color":{"text":"d"}}}}}"##,
            ),
            b"theme",
        ),
    ]));
    assert_php_eq(
        &actual,
        &json(
            r##"{"settings":{"color":{"custom":true,"palette":{"default":[{"color":"#f00","name":"Red","slug":"red"}],"theme":[{"color":"#00f","name":"Blue","slug":"blue"}]},"text":false}},"styles":{"blocks":{"core/group":{"color":{"text":"d"}},"core/paragraph":{"color":{"background":"c","text":"b"}}}},"version":3}"##,
        ),
    );
}

