#[test]
fn merge_keeps_existing_block_order_and_appends_new() {
    let deps = deps();
    let blocks = MemoryBlockMetadata::new();
    for name in ["a/a", "b/b", "c/c"] {
        blocks.register(RegisteredBlock {
            name: name.to_owned(),
            selectors: Value::Null,
            supports: Value::Null,
            style_names: vec![],
        });
    }
    let deps = ThemeJsonDeps {
        blocks: Rc::new(blocks),
        ..deps
    };
    let base = construct(
        json(
            r##"{"version":3,"styles":{"blocks":{"a/a":{"color":{"text":"1"}},"b/b":{"color":{"text":"2"}}}}}"##,
        ),
        b"theme",
        &deps,
    );
    let incoming = construct(
        json(
            r##"{"version":3,"styles":{"blocks":{"c/c":{"color":{"text":"3"}},"a/a":{"color":{"text":"4"}}}}}"##,
        ),
        b"custom",
        &deps,
    );
    let merged = raw(merge(&base, &incoming, &deps));
    let blocks = speedyspec_wp_theme_json::array_path::get(&merged, &["styles", "blocks"]).unwrap();
    let Value::Array(entries) = blocks else {
        panic!()
    };
    let names: Vec<String> = entries.iter().map(|(k, _)| format!("{k:?}")).collect();
    assert_eq!(names, [r#"Str("a/a")"#, r#"Str("b/b")"#, r#"Str("c/c")"#]);
}
